examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchButton({{back}}, systemImage: "chevron.left", variant: .ghost, size: .sm) {}
    HStack(alignment: .top, spacing: MonarchTokens.Space.space3) {
        MonarchAvatar(image: nil, name: {{name}}, size: .lg, isDecorative: true)
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
            Text({{name}})
                .monarchTextStyle(.title)
                .accessibilityAddTraits(.isHeader)
            MonarchFlowLayout(spacing: MonarchTokens.Space.space2) {
                MonarchStatusBadge(MonarchStatusDefinition({{status.label}}, tone: {{status.tone|tone}}, systemImage: "checkmark.circle"))
                MonarchBadge({{badge.label}}, tone: {{badge.tone|tone}})
            }
            Text(verbatim: {{subtitle}})
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textMuted)
            HStack(spacing: MonarchTokens.Space.space2) {
                MonarchButton({{action}}, variant: .secondary) {}
                Menu {
                    Button({{menu.0}}) {}
                    Button({{menu.1}}) {}
                    Button({{menu.2}}, role: .destructive) {}
                } label: {
                    Label("More actions for " + {{name}}, systemImage: "ellipsis")
                        .labelStyle(.iconOnly)
                }
                .buttonStyle(.monarch(.secondary))
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
    MonarchKeyValue(
        [
            MonarchKeyValueItem({{facts.0.term}}, value: {{facts.0.value}}),
            MonarchKeyValueItem({{facts.1.term}}, value: {{facts.1.value}}),
            MonarchKeyValueItem({{facts.2.term}}, value: {{facts.2.value}}, isCopyable: {{facts.2.copyable}}),
            MonarchKeyValueItem({{facts.3.term}}, value: {{facts.3.value}}),
        ],
        separator: .none,
        layout: .stack,
        emptyLabel: "—"
    )
    MonarchTabs(
        "Contact sections",
        selection: $section,
        items: [
            MonarchTabsItem({{tabs.0}}, value: {{tabs.0}}),
            MonarchTabsItem({{tabs.1}}, value: {{tabs.1}}),
            MonarchTabsItem({{tabs.2}}, value: {{tabs.2}}),
        ]
    )
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchButton("All contacts", systemImage: "chevron.left", variant: .ghost, size: .sm) {}
    HStack(alignment: .top, spacing: MonarchTokens.Space.space3) {
        MonarchAvatar(image: nil, name: "Ada Lovelace", size: .lg, isDecorative: true)
        VStack(alignment: .leading, spacing: MonarchTokens.Space.space2) {
            Text("Ada Lovelace")
                .monarchTextStyle(.title)
                .accessibilityAddTraits(.isHeader)
            MonarchFlowLayout(spacing: MonarchTokens.Space.space2) {
                MonarchStatusBadge(MonarchStatusDefinition("Active", tone: .success, systemImage: "checkmark.circle"))
                MonarchBadge("Enterprise", tone: .neutral)
            }
            Text(verbatim: "ada@example.com · Head of Engineering, Northfield")
                .monarchTextStyle(.bodySmall)
                .foregroundStyle(theme.colors.textMuted)
            HStack(spacing: MonarchTokens.Space.space2) {
                MonarchButton("Email", variant: .secondary) {}
                Menu {
                    Button("Merge") {}
                    Button("Archive") {}
                    Button("Delete contact", role: .destructive) {}
                } label: {
                    Label("More actions for " + "Ada Lovelace", systemImage: "ellipsis")
                        .labelStyle(.iconOnly)
                }
                .buttonStyle(.monarch(.secondary))
            }
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }
    MonarchKeyValue(
        [
            MonarchKeyValueItem("Owner", value: "Grace Hopper"),
            MonarchKeyValueItem("Lifecycle", value: "Customer"),
            MonarchKeyValueItem("Contact ID", value: "c_1042", isCopyable: true),
            MonarchKeyValueItem("Phone", value: nil),
        ],
        separator: .none,
        layout: .stack,
        emptyLabel: "—"
    )
    MonarchTabs(
        "Contact sections",
        selection: $section,
        items: [
            MonarchTabsItem("Overview", value: "Overview"),
            MonarchTabsItem("Activity", value: "Activity"),
            MonarchTabsItem("Deals", value: "Deals"),
        ]
    )
}
